$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1')
if(-not(Test-Command python)){throw 'Python requerido. Ejecuta -Python primero'};& python -m pip install --user --quiet --upgrade platformio;$p=Join-Path $HOME 'AppData\Roaming\Python\Scripts';$env:PATH="$p;$env:PATH";Ensure-PathLine "`$env:PATH = `"$p;`$env:PATH`"" (Get-UserProfile);if(-not(Test-Command pio)){throw 'pio no disponible tras instalación'};Write-Ok "PlatformIO $(& pio --version) instalado";& pio pkg install --global --platform espressif32
